import ( 'context' 'fmt' 'io' 'os' 'os/signal' 'syscall' 'time'
'github.com/labstack/gommon/log' 'gopkg.in/natefinch/lumberjack.v2' metav1 'k8s.io/apimachinery/pkg/apis/meta/v1' 'k8s.io/client-go/kubernetes' 'k8s.io/client-go/rest' 'k8s.io/client-go/tools/clientcmd' 'k8s.io/client-go/tools/leaderelection' 'k8s.io/client-go/tools/leaderelection/resourcelock' )
// 选主核心配置 const ( leaderLockName = 'alertmanager-webhook-leader-lock' leaderLockNamespace = 'monitoring' // Leader 身份的「最大有效期」 / Lease 锁的「租期时长」 leaseDuration = 15 * time.Second // Leader 的「续约超时时间」 / 「身份续命窗口期」 renewDeadline = 10 * time.Second
// 两种场景下的「重试间隔」（最灵活的参数，控制集群抢主效率），覆盖所有非 Leader 实例 + Leader 续约失败场景： // 场景①：Follower 实例（非 Leader）的「抢主重试间隔」。

# 编译部署（nginx-1.24为例）
1. 下载gmssl_openssl_1.1_bxx.tar.gz到/root/下

打开地址 https://www.gmssl.cn/gmssl/index.jsp 
选择架构下载
<img width='1558' height='613' alt='Image' src='https://github.com/user-attachments/assets/3e9a0e6b-59ca-4d79-a11d-fed3ffe9e979' />

2. 解压 tar xzfm gmssl_openssl_1.1_bxx.tar.gz -C /usr/local
3. 下载[nginx-1.24.0.tar.gz](http://nginx.org/download/nginx-1.24.0.tar.gz)到/root/下
4. 解压 tar xzfm nginx-1.24.0.tar.gz
5. 进入目录 cd /root/nginx-1.24.0
6. 编辑auto/lib/openssl/conf，将全部$OPENSSL/.openssl/修改为$OPENSSL/并保存(sed -i 's|$OPENSSL/.openssl/|$OPENSSL/|g'  auto/lib/openssl/conf)
7. 编译配置
```
./configure \
--without-http_gzip_module \
--with-http_ssl_module \
--with-http_stub_status_module \
--with-http_v2_module \
--with-stream \
--with-file-aio \
--with-openssl='/usr/local/gmssl'
```
8. 编译安装
```
make install
```
9. /usr/local/nginx即为生成的nginx目录
> [ !TIP ]
> 可能需要使用`yum install -y zlib zlib-devel pcre pcre-devel`或者`apt-get install libpcre3 libpcre3-dev zlib1g zlib1g-dev`

# 直接下载
打开地址 https://www.gmssl.cn/gmssl/index.jsp 
<img width='1443' height='611' alt='Image' src='https://github.com/user-attachments/assets/a1574f62-f243-4fd8-9b99-edac252708ae' />

# 测试：
自己使用gmssl生成证书，即根据[sm2国密证书创建](https://longxiucai.github.io/post/84.html)文中提供的方法
需要到下面地址中解密nginx-sm2.key之后nginx才能使用
https://www.gmcrt.cn/gmcrt/index.jsp
<img width='1595' height='519' alt='Image' src='https://github.com/user-attachments/assets/6a4120c0-2608-4271-9994-cf27f790da3c' />

将nginx-sm2.cert与nginx-sm2.decrypted.pem放到/usr/local/nginx/conf/cert/下

/usr/local/nginx/conf/nginx.conf配置如下
```
worker_processes  auto;
error_log  /var/log/nginx/error.log;
pid        /var/run/nginx.pid;

events {
    worker_connections  1024;
}

http {
    include       mime.types;
    default_type  application/octet-stream;

    sendfile        on;
    keepalive_timeout  65;
    server {
        listen 80;
        return 301 https://$host$request_uri;
    }
    server {
        listen 443 ssl;
        # 自己的证书
        ssl_certificate /usr/local/nginx/conf/cert/nginx-sm2.cert;
        ssl_certificate_key /usr/local/nginx/conf/cert/nginx-sm2.decrypted.pem; ##解密之后的key
        ssl_protocols TLSv1.1 TLSv1.2 TLSv1.3;
	#配置ssl证书所需的加密套件
        ssl_ciphers ECDHE-RSA-AES128-GCM-SHA256:AES128-SHA:DES-CBC3-SHA:ECC-SM4-CBC-SM3:ECC-SM4-GCM-SM3;
        ssl_verify_client off;
        ssl_session_cache shared:SSL:10m;
        ssl_session_timeout 10m;

        root /usr/local/nginx/html;
        index index.html;
        location / {
            try_files $uri $uri/ =404;
        }
    }
}

```

# nginx配置
## 配置示例(国密单向)
```
server
{
  listen 0.0.0.0:1443 ssl;
  ssl_protocols TLSv1 TLSv1.1 TLSv1.2;
  ssl_ciphers ECDHE-RSA-AES128-GCM-SHA256:AES128-SHA:DES-CBC3-SHA:ECC-SM4-CBC-SM3:ECC-SM4-GCM-SM3;
  ssl_verify_client off;

  ssl_certificate keystore/sm2.demo1.gmssl.cn.sig.crt.pem;
  ssl_certificate_key keystore/sm2.demo1.gmssl.cn.sig.key.pem;

  ssl_certificate keystore/sm2.demo1.gmssl.cn.enc.crt.pem;
  ssl_certificate_key keystore/sm2.demo1.gmssl.cn.enc.key.pem;

  location /
  {
    root html;
    index index.html index.htm;
  }
}
```
注释：测试证书使用[www.gmcrt.cn](https://www.gmcrt.cn/)签发。

# Load test types

## Smoke testing

```
import http from 'k6/http';
import { check, sleep } from 'k6';
export const options = {
  vus: 3, // Key for Smoke test. Keep it at 2, 3, max 5 VUs
  duration: '1m', // This can be shorter or just a few iterations
};
export default () => {
  const urlRes = http.get('https://quickpizza.grafana.com');
  sleep(1);
  // MORE STEPS
  // Add only the processes that will be on high demand
  // Step1
  // Step2
  // etc.
};
```

![The shape of the smoke test as configured in the preceding script](https://grafana.com/media/docs/k6-oss/chart-smoke-test-k6-script-example.png)

## Average-load testing

```
import http from 'k6/http';
import { sleep } from 'k6';
export const options = {
  // Key configurations for avg load test in this section
  stages: [
    { duration: '5m', target: 100 }, // traffic ramp-up from 1 to 100 users over 5 minutes.
    { duration: '30m', target: 100 }, // stay at 100 users for 30 minutes
    { duration: '5m', target: 0 }, // ramp-down to 0 users
  ],
};
export default () => {
  const urlRes = http.get('https://quickpizza.grafana.com');
  sleep(1);
};
```

![The shape of the average-load test as configured in the preceding script](https://grafana.com/media/docs/k6-oss/chart-average-load-test-k6-script-example.png)

## Stress testing

```
import http from 'k6/http';
import { sleep } from 'k6';

export const options = {
  // Key configurations for Stress in this section
  stages: [
    { duration: '10m', target: 200 }, // traffic ramp-up from 1 to a higher 200 users over 10 minutes.
    { duration: '30m', target: 200 }, // stay at higher 200 users for 30 minutes
    { duration: '5m', target: 0 }, // ramp-down to 0 users
  ],
};

export default () => {
  const urlRes = http.get('https://quickpizza.grafana.com');
  sleep(1);
};
```

![The shape of the stress test as configured in the preceding script](https://grafana.com/media/docs/k6-oss/chart-stress-test-k6-script-example.png)

## Soak testing

```
import http from 'k6/http';
import { sleep } from 'k6';

export const options = {
  // Key configurations for Soak test in this section
  stages: [
    { duration: '5m', target: 100 }, // traffic ramp-up from 1 to 100 users over 5 minutes.
    { duration: '8h', target: 100 }, // stay at 100 users for 8 hours!!!
    { duration: '5m', target: 0 }, // ramp-down to 0 users
  ],
};

export default () => {
  const urlRes = http.get('https://quickpizza.grafana.com');
  sleep(1);
};
```

![The shape of the soak test as configured in the preceding script](https://grafana.com/media/docs/k6-oss/chart-soak-test-k6-script-example.png)

## Spike testing

```
import http from 'k6/http';
import { sleep } from 'k6';

export const options = {
  // Key configurations for spike in this section
  stages: [
    { duration: '2m', target: 2000 }, // fast ramp-up to a high point
    // No plateau
    { duration: '1m', target: 0 }, // quick ramp-down to 0 users
  ],
};

export default () => {
  const urlRes = http.get('https://quickpizza.grafana.com');
  sleep(1);
};
```

![The shape of the spike test as configured in the preceding script](https://grafana.com/media/docs/k6-oss/chart-spike-test-k6-script-example.png)

## Breakpoint testing

```
import http from 'k6/http';
import { sleep } from 'k6';

export const options = {
  // Key configurations for breakpoint in this section
  executor: 'ramping-arrival-rate', //Assure load increase if the system slows
  stages: [
    { duration: '2h', target: 20000 }, // just slowly ramp-up to a HUGE load
  ],
};

export default () => {
  const urlRes = http.get('https://quickpizza.grafana.com');
  sleep(1);
};
```

![The shape of the breakpoint test as configured in the preceding script](https://grafana.com/media/docs/k6-oss/chart-breakpoint-test-k6-script-example.png)
