## c程序打开多个文件
```
#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>

int *fds = NULL;
int number_of_files = 0;
int last_files = 0;
void cleanup() {
    if (fds != NULL) {
        for (int i = 0; i < last_files + 1; i++) {
            if (fds[i] != -1) {
                close(fds[i]);
                printf('Closed file descriptor %d\n', fds[i]);
            }

            char filename[256];
            snprintf(filename, sizeof(filename), '/tmp/testfile_%d.txt', i);
            if (unlink(filename) == 0) {
                printf('Deleted file %s\n', filename);
            } else {
                perror('unlink');
            }
        }
        free(fds);
        fds = NULL;
        printf('Freed allocated memory\n');
    }
}

void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf('\nCaught SIGINT signal, performing cleanup...\n');
        cleanup();
        exit(EXIT_FAILURE);
    }
}

void open_many_files(int num_files) {
    number_of_files = num_files;
    fds = malloc(number_of_files * sizeof(int));
    if (fds == NULL) {
        perror('malloc');
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < number_of_files; i++) {
        char filename[256];
        snprintf(filename, sizeof(filename), '/tmp/testfile_%d.txt', i);
        fds[i] = open(filename, O_RDWR | O_CREAT, 0644);
        if (fds[i] == -1) {
            perror('open');
            break;
        }
        printf('Opened file descriptor %d for %s\n', fds[i], filename);
        last_files = i;
    }
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, 'Usage: %s <number_of_files_to_open> <wait_time_in_seconds>\n', argv[0]);
        exit(EXIT_FAILURE);
    }

    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    int num_files_to_open = atoi(argv[1]);
    int wait_time = atoi(argv[2]);

    open_many_files(num_files_to_open);

    // Wait for the specified time before closing file descriptors
    printf('Waiting for %d seconds before closing file descriptors...\n', wait_time);
    sleep(wait_time);

    cleanup();

    return 0;
}
```
## 在pod中复现`too many open files in system`的情况
*  修改limit.conf中nofile，现在文件打开数量，在pod中不会报错，直接在宿主机中运行程序会报错
*  修改内核参数fs.file-max，降低值内核参数的值，pod中会报错。

## C代码：thread.c
```
#include<stdio.h>
#include<stdlib.h>
#include<pthread.h>
#include <unistd.h> 
/* 声明结构体 */
struct member
{
    int num;
    char *name;
};     

/* 定义线程pthread */
static void * pthread(void *arg)       
{
    struct member *temp;
    
    /* 线程pthread开始运行 */
    printf('pthread start!\n');
    while(1){
    ;
    }
    /* 令主线程继续执行 */
    sleep(2);
    
    /* 打印传入参数 */
    temp = (struct member *)arg;      
    printf('member->num:%d\n',temp->num);
    printf('member->name:%s\n',temp->name);
    
    return NULL;
}

/* main函数 */
int main(int agrc,char* argv[])
{
    pthread_t tidp,tidp1;
    struct member *b;

    /* 为结构体变量b赋值 */
    b = (struct member *)malloc(sizeof(struct member));           
    b->num=1;
    b->name='mlq';              

    /* 创建线程pthread */
    if ((pthread_create(&tidp, NULL, pthread, (void*)b)) == -1)
    {
        printf('create error!\n');
        return 1;
    }
    if ((pthread_create(&tidp1, NULL, pthread, (void*)b)) == -1)
    {
        printf('create error!\n');
        return 1;
    }

    /* 令线程pthread先运行 */
    sleep(1);
    
    /* 线程pthread睡眠2s，此时main可以先执行 */
    printf('main continue!\n');
    
    /* 等待线程pthread释放 */
    if (pthread_join(tidp, NULL))                  
    {
        printf('thread is not exit...\n');
        return -2;
    }
    
    return 0;
}
```
## 编译
```
gcc -o thread.out thread.c -lpthread
```
## 测试
1、`systemd-run --unit=threadtest --slice=test  /root/thread.out` 会启动一个临时服务,该服务就是运行/root/thread.out，名为threadtest.service
2、查看`top -H -p <threadtest.service的pid>`会显示该服务及其线程的信息
3、cgroup：/sys/fs/cgroup/cpu/test.slice/threadtest.service。

```
package cert

import (
	'crypto/x509'
	'encoding/pem'
	'os'
	'path/filepath'
	'strings'
	'time'

	log 'github.com/sirupsen/logrus'
)

func parseCertificate(file string) {
	// 读取文件内容
	fileData, err := os.ReadFile(file)
	if err != nil {
		log.Errorf('Error reading file %s: %s\n', file, err)
		return
	}

	// 解析 PEM 块
	block, _ := pem.Decode(fileData)
	if block == nil {
		log.Errorf('No PEM block found in file %s\n', file)
		return
	}

	// 判断文件类型
	fileType := strings.ToLower(filepath.Ext(file))
	switch fileType {
	case '.crt', '.pem':
		// 解析证书
		cert, err := x509.ParseCertificate(block.Bytes)
		if err != nil {
			log.Errorf('Error parsing certificate from file %s: %s\n', file, err)
			return
		}

		// 输出证书有效期等信息
		log.Infof('Certificate in file %s:', file)
		log.Infof('  Subject: %s', cert.Subject.CommonName)
		log.Infof('  Valid from: %s', cert.NotBefore)
		log.Infof('  Valid until: %s', cert.NotAfter)

		// 计算证书有效期结束时间与当前时间之间的天数差
		now := time.Now()
		expiresInDays := int((time.Duration(cert.NotAfter.Sub(now).Hours()) / 24))
		log.Infof('证书%s 将于 %d 天后过期', cert.Subject.CommonName, expiresInDays)
		log.Infof('---------------------------')
	default:
		log.Infof('Unsupported file type: %s %s', fileType, file)
	}
}
```。

```
package dbtest

import (
	'database/sql'
	'fmt'
	'log'

	_ 'github.com/go-sql-driver/mysql'
)

func maindb() {
	// 连接 MySQL 数据库
	db, err := sql.Open('mysql', 'dbinit:123456@tcp(10.42.186.232:3306)/dbinit_test')
	if err != nil {
		log.Fatal(err)
	}
	defer db.Close()

	// 测试连接
	err = db.Ping()
	if err != nil {
		log.Fatal('Error connecting to the database:', err)
	}

	fmt.Println('Connected to MySQL database successfully!')

	// 查询示例
	rows, err := db.Query('SELECT * FROM users')
	if err != nil {
		log.Fatal('Error executing query:', err)
	}
	defer rows.Close()

	// 遍历查询结果
	for rows.Next() {
		var id int
		var name string
		err := rows.Scan(&id, &name)
		if err != nil {
			log.Fatal('Error scanning row:', err)
		}
		fmt.Printf('ID: %d, Name: %s\n', id, name)
	}
}
